import '../../domain/feature.dart';

/// The comment at the top of every file bdd_flutter rewrites on each build.
String generatedHeader(Feature feature) {
  return '// GENERATED CODE - DO NOT MODIFY BY HAND.\n'
      '// Generated by bdd_flutter from ${feature.fileName}.feature.\n'
      '// Run `dart run bdd_flutter build` after changing the feature.\n\n';
}
